#!/bin/bash
#SBATCH --job-name=fb3d_a2fix
#SBATCH --partition=gpu-xe9680q
#SBATCH --gres=gpu:1
#SBATCH --time=08:00:00
#SBATCH --ntasks=1
#SBATCH --cpus-per-task=8
#SBATCH --mem=64G
#SBATCH --array=1-20%8
#SBATCH --output=logs/paper_reruns/a2fix_%A_%a.out
#SBATCH --error=logs/paper_reruns/a2fix_%A_%a.err

# A2 retrained with early stopping disabled. thread facebase3d-a2diag-2026-09-04.
# Rationale and evidence: see the A2_FIX block in facebench/eval/rerun_config.py.
# Joblist is GENERATED by make_fix_jobs.py --family A2_fix — do not hand-edit it.
set -euo pipefail

JOBLIST="${FACEBENCH_ROOT:?set FACEBENCH_ROOT to the repository root}"/facebench/eval/a2_fix_joblist.txt
N=$(grep -c . "$JOBLIST")
if [ "$N" -ne 20 ]; then
  echo "joblist has $N lines, expected 20 — refusing" >&2; exit 1
fi
CMD=$(sed -n "${SLURM_ARRAY_TASK_ID}p" "$JOBLIST")

echo "A2 fix array — task ${SLURM_ARRAY_TASK_ID}/20"
echo "Node: $(hostname)  GPU: ${CUDA_VISIBLE_DEVICES:-none}"
echo "CMD: $CMD"
date
eval "$CMD"
echo "Done at $(date)"
